 QJsonObject quote{{"source","新浪公开报价"},{"price",9.2},{"tradeDate","2026-10-12"},{"tradeTime","15:00:00"},{"checkedAt","2026-10-12T07:01:00Z"},{"cached",true},{"error","EOF"}};
